UPDATE afv_canvas_text_job SET result_json = #{result}, result_hash = #{hash}, received_at = UTC_TIMESTAMP(6),
    permit_held = FALSE, revision = revision + 1, updated_at = UTC_TIMESTAMP(6)
WHERE id = #{id} AND request_started_at IS NOT NULL AND request_owner_instance_id = #{owner} AND request_owner_epoch = #{epoch}
